import{_ as l,o as t,c as i,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2020-02-26 :: Ceph Docubetter Meeting","description":"","frontmatter":{"title":"2020-02-26 :: Ceph Docubetter Meeting","date":"2020-02-26T00:00:00.000Z","updated":"2020-04-04T00:00:00.000Z","tags":["Ceph","文档更新","版本特定更改","会议纪要","问题修复"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-02-26_-_-_Ceph_Docubetter_Meeting.md","filePath":"posts/2020/2020-02-26_-_-_Ceph_Docubetter_Meeting.md","lastUpdated":1780460162000}'),o={name:"posts/2020/2020-02-26_-_-_Ceph_Docubetter_Meeting.md"};function r(n,e,s,u,p,_){return t(),i("div",null,[...e[0]||(e[0]=[a('<p>会议纪要</p><h3 id="参与者" tabindex="-1">参与者 <a class="header-anchor" href="#参与者" aria-label="Permalink to &quot;参与者&quot;">​</a></h3><ul><li>Anthony Jat (文档结构化记录请求提出者)</li><li>David Zapman 等其他参与者</li></ul><h3 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h3><ol><li><p><strong>文档更新与审核</strong></p><ul><li>完成了PG修复页面更新，待批准。</li><li>正在完善CephFS、Ceph OSD DDF和Set Object Store Tool的文档。</li><li>每周发送文档审核请求，确保准确性和完整性。</li></ul></li><li><p><strong>版本特定更改的记录</strong></p><ul><li>Anthony 提出需以更结构化的方式记录版本特定更改，特别是mano s daemon down reporters的行为变化。</li><li>讨论了在发布说明中如何更好地记录这些更改，并确保技术准确性。</li></ul></li><li><p><strong>网站搜索功能问题</strong></p><ul><li>报告了网站搜索功能不工作的问题，计划进行本地测试和修复。</li></ul></li><li><p><strong>FreeBSD安装文档</strong></p><ul><li>计划在Octopus发布后，协助编写FreeBSD安装文档。</li></ul></li><li><p><strong>文档质量提升</strong></p><ul><li>讨论了通过标签和审核流程提升文档质量的方法。</li></ul></li><li><p><strong>未来会议和活动</strong></p><ul><li>讨论了新冠病毒影响下，可能取消或转为线上的开发者会议。</li></ul></li></ol><h3 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h3><ul><li>确认文档更新进度和下一步计划。</li><li>同意在发布说明中更严格地记录和审核版本特定更改。</li><li>计划修复网站搜索功能。</li><li>确认FreeBSD安装文档编写计划。</li><li>讨论提升文档质量的措施。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li>继续完善和审核文档。</li><li>确保发布说明中包含所有必要的版本特定更改。</li><li>修复网站搜索功能。</li><li>协助编写FreeBSD安装文档。</li><li>关注并参与可能的线上开发者会议。</li></ul><h3 id="下次会议" tabindex="-1">下次会议 <a class="header-anchor" href="#下次会议" aria-label="Permalink to &quot;下次会议&quot;">​</a></h3><ul><li>计划在两周后举行，时间将更适应北美地区。</li></ul>',11)])])}const c=l(o,[["render",r]]);export{d as __pageData,c as default};
